        // ---- MODÈLES 3D EN BLOCS : un maillage (acheté, importé en STL) posé comme un bloc ; plan = son contour vu de dessus, 3D = le maillage en facettes, à la taille réelle.
        //      Sommets en mm entiers (int16, centre au milieu, sol à z = 0, avant vers +x), triangles indexés ; chaque pièce garde sa couleur (le pinceau la change).
        //      Modèles importés : gardés sur ce poste et dans chaque plan qui les utilise (le fichier s'ouvre ailleurs avec eux).
        const MDL_STORE = {};
        const MDL_BUILTIN = {
            twingo1: { name: 'Twingo 1', tab: 'mobil', wheels: [[1101, 643, 265, 256, 226], [1101, -643, 265, 256, 226], [-1120, 643, 265, 256, 226], [-1120, -643, 265, 256, 226]], parts: [
                { nm: 'carrosserie', c: 0x3f6fb0, n: 3773, v: '', i: '' }
            ] } };
        const b64Bytes = (s) => { const t = atob(s), u = new Uint8Array(t.length); for (let i = 0; i < t.length; i++) u[i] = t.charCodeAt(i); return u.buffer; };
        const bytesB64 = (buf) => { const u = new Uint8Array(buf); let s = ''; for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode.apply(null, u.subarray(i, i + 0x8000)); return btoa(s); };
        // une pièce décodée une fois : sommets (mm) et triangles ; wheels : [x, y, z, rayon, largeur] (mm) → cylindres
        function mdlPart(p) { if (!p._d) { const v = new Int16Array(b64Bytes(p.v)), ib = b64Bytes(p.i), i = p.n > 65535 ? new Uint32Array(ib) : new Uint16Array(ib); Object.defineProperty(p, '_d', { value: { v, i }, enumerable: false, writable: true }); } return p._d; }
        // géométries THREE (m) de toutes les pièces : [géométrie, couleur]
        function mdlParts(id) { const M = MDL_STORE[id]; if (!M) return []; return M.parts.map(p => { const d = mdlPart(p), pos = new Float32Array(d.v.length); for (let k = 0; k < pos.length; k++) pos[k] = d.v[k] / 1000;
            const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.BufferAttribute(pos, 3)); g.setIndex(new THREE.BufferAttribute(d.i.slice(), 1)); return [g, p.c]; })
            .concat((M.wheels || []).map(([x, y, z, r, w]) => { const g = new THREE.CylinderGeometry(r / 1000, r / 1000, w / 1000, 14); g.translate(x / 1000, y / 1000, z / 1000); return [g, 0x1f2937]; })); }   /* roues : de simples cylindres (centre, rayon, largeur en mm) */
        // contour vu de dessus (enveloppe convexe, mm) : le dessin du bloc en plan
        function mdlHull(id) { const P = []; MDL_STORE[id].parts.forEach(p => { const v = mdlPart(p).v; for (let k = 0; k < v.length; k += 3) P.push([v[k], v[k + 1]]); });
            P.sort((a, b) => a[0] - b[0] || a[1] - b[1]); const cr = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]), lo = [], hi = [];
            for (const p of P) { while (lo.length >= 2 && cr(lo[lo.length - 2], lo[lo.length - 1], p) <= 0) lo.pop(); lo.push(p); } for (let k = P.length - 1; k >= 0; k--) { const p = P[k]; while (hi.length >= 2 && cr(hi[hi.length - 2], hi[hi.length - 1], p) <= 0) hi.pop(); hi.push(p); }
            const H = lo.slice(0, -1).concat(hi.slice(0, -1)); return H.filter((q, k) => k === 0 || Math.hypot(q[0] - H[k - 1][0], q[1] - H[k - 1][1]) > 40); }
        function mdlBlock(id, user) { const M = MDL_STORE[id], H = mdlHull(id), x0 = Math.min(...H.map(q => q[0])), x1 = Math.max(...H.map(q => q[0])), w = (x1 - x0) * 0.06;
            return Object.assign({ id: 'mdl-' + id, tab: BLK_TABS.some(t => t.id === M.tab) ? M.tab : 'mobil', name: M.name, el: [['P', H, 1], ['L', x1 - w, 0, x1 - 3 * w, w], ['L', x1 - w, 0, x1 - 3 * w, -w]], mdl: id }, user ? { user: 1 } : {}); }   /* petite flèche : l'avant */
        Object.keys(MDL_BUILTIN).forEach(k => { MDL_STORE[k] = MDL_BUILTIN[k]; BLOCKS_BUILTIN.push(mdlBlock(k)); });
        // modèles importés sur ce poste
        try { const U = JSON.parse(localStorage.getItem('momocad-mdl') || '{}'); Object.keys(U).forEach(k => { if (!MDL_STORE[k] && U[k] && Array.isArray(U[k].parts)) MDL_STORE[k] = U[k]; }); } catch (e) {}
        function mdlUserSave() { const U = {}; Object.keys(MDL_STORE).forEach(k => { if (MDL_STORE[k].user) U[k] = MDL_STORE[k]; }); try { localStorage.setItem('momocad-mdl', JSON.stringify(U)); return true; } catch (e) { return false; } }
        // ---- import STL : binaire ou texte ; réduit en facettes (regroupement des sommets proches), mis à la taille réelle, posé au sol
        function stlTris(buf) { const dv = new DataView(buf), n = buf.byteLength >= 84 ? dv.getUint32(80, true) : 0;
            if (n > 0 && 84 + n * 50 === buf.byteLength) { const t = new Float32Array(n * 9); for (let i = 0; i < n; i++) for (let k = 0; k < 9; k++) t[i * 9 + k] = dv.getFloat32(84 + i * 50 + 12 + k * 4, true); return t; }
            const txt = new TextDecoder().decode(buf), V = []; txt.replace(/vertex\s+([-+0-9.eE]+)\s+([-+0-9.eE]+)\s+([-+0-9.eE]+)/g, (m0, a, b, c) => { V.push(+a, +b, +c); return ''; }); return V.length >= 9 ? new Float32Array(V.length - V.length % 9).map((_, k) => V[k]) : null; }
        // sommets à moins de g regroupés : maillage léger (facettes), triangles écrasés retirés
        function mdlDecimate(t, g) { const key = new Map(), S = [], idx = []; for (let k = 0; k < t.length; k += 3) { const kk = Math.round(t[k] / g) + ',' + Math.round(t[k + 1] / g) + ',' + Math.round(t[k + 2] / g); let j = key.get(kk); if (j === undefined) { j = S.length / 4; key.set(kk, j); S.push(0, 0, 0, 0); } S[j * 4] += t[k]; S[j * 4 + 1] += t[k + 1]; S[j * 4 + 2] += t[k + 2]; S[j * 4 + 3]++; idx.push(j); }
            const nV = S.length / 4, v = new Int16Array(nV * 3); for (let j = 0; j < nV; j++) for (let c = 0; c < 3; c++) v[j * 3 + c] = Math.max(-32767, Math.min(32767, Math.round(S[j * 4 + c] / S[j * 4 + 3])));
            const I = [], seen = new Set(); for (let k = 0; k < idx.length; k += 3) { const a = idx[k], b = idx[k + 1], c = idx[k + 2]; if (a === b || b === c || a === c) continue; const s = [a, b, c].sort((x, y) => x - y).join(','); if (seen.has(s)) continue; seen.add(s); I.push(a, b, c); }
            return { v, i: nV > 65535 ? new Uint32Array(I) : new Uint16Array(I), n: nV }; }
        // triangles (unités du fichier) → pièce prête : haut choisi (z ou y), longueur réelle L (mm) sur le plus grand côté, centrée, au sol ; au plus ~16 000 triangles
        function mdlFromTris(t, Lmm, up) { const n = t.length / 3, P = new Float32Array(t.length); for (let k = 0; k < n; k++) { const x = t[k * 3], y = t[k * 3 + 1], z = t[k * 3 + 2]; if (up === 'y') { P[k * 3] = x; P[k * 3 + 1] = -z; P[k * 3 + 2] = y; } else { P[k * 3] = x; P[k * 3 + 1] = y; P[k * 3 + 2] = z; } }
            let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity, z0 = Infinity; for (let k = 0; k < n; k++) { x0 = Math.min(x0, P[k * 3]); x1 = Math.max(x1, P[k * 3]); y0 = Math.min(y0, P[k * 3 + 1]); y1 = Math.max(y1, P[k * 3 + 1]); z0 = Math.min(z0, P[k * 3 + 2]); }
            const long = Math.max(x1 - x0, y1 - y0) || 1, s = Lmm / long, rot = (y1 - y0) > (x1 - x0), cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;   /* le plus grand côté selon x (l'avant vers +x) */
            for (let k = 0; k < n; k++) { const x = (P[k * 3] - cx) * s, y = (P[k * 3 + 1] - cy) * s; P[k * 3] = rot ? y : x; P[k * 3 + 1] = rot ? -x : y; P[k * 3 + 2] = (P[k * 3 + 2] - z0) * s; }
            let g = Lmm / 400, r = mdlDecimate(P, g); for (let k = 0; k < 6 && r.i.length / 3 > 16000; k++) { g *= 1.4; r = mdlDecimate(P, g); } return r; }
        async function mdlImport(file) { if (!file) return; const buf = await file.arrayBuffer(), t = stlTris(buf); if (!t || t.length < 9) { mcToast('Fichier STL illisible (aucun triangle).'); return; }
            const nm0 = String(file.name || 'Modèle').replace(/\.stl$/i, ''), inp = (id, v, w) => `<input id="${id}" type="text" value="${MF.esc(v)}" class="mf-in" style="width:${w || '6rem'}">`;
            openTopoModal('🧊 Modèle 3D (STL)', `<div style="display:flex;flex-direction:column;gap:8px;font-size:13.5px;color:#e5e7eb;min-width:340px">
                <div class="mf-hint" style="margin:0">${(t.length / 9).toLocaleString('fr-FR')} triangles. Il devient un bloc 2D/3D : contour vu de dessus en plan, maquette en facettes en 3D, posée au sol. Gardé sur ce poste et dans les plans qui l'utilisent.</div>
                ${MF.row('Nom', inp('mdl-nm', nm0, '12rem'), '')}${MF.row('Longueur réelle <span class="mf-hint">(le plus grand côté)</span>', inp('mdl-L', '3,43'), 'm')}
                ${MF.row('Haut du modèle', `<select id="mdl-up" class="mf-in"><option value="z">Z (impression 3D)</option><option value="y">Y (export 3D)</option></select>`, '')}
                ${MF.row('Rangé dans', `<select id="mdl-tab" class="mf-in">${BLK_TABS.map(b => `<option value="${b.id}"${b.id === (blkTab || 'mobil') ? ' selected' : ''}>${b.name}</option>`).join('')}</select>`, '')}
                ${MF.row('Couleur', `<input id="mdl-c" type="color" value="#9ca3af">`, '')}</div>`,
                [['Annuler', () => closeTopoModal(), false], ['Ajouter', () => { const L = t2Num(document.getElementById('mdl-L').value); if (!(L > 0 && L < 1000)) { mcToast('Longueur réelle à donner en mètres.'); return; }
                    const r = mdlFromTris(t, L * 1000, document.getElementById('mdl-up').value), id = 'u' + Date.now().toString(36), c = parseInt(document.getElementById('mdl-c').value.slice(1), 16);
                    MDL_STORE[id] = { name: document.getElementById('mdl-nm').value.trim() || nm0, tab: document.getElementById('mdl-tab').value, user: 1, parts: [{ nm: 'corps', c, n: r.n, v: bytesB64(r.v.buffer), i: bytesB64(r.i.buffer) }] };
                    const b = mdlBlock(id, true); userBlocks.push(b); const ok = mdlUserSave(); try { localStorage.setItem('momocad-blocks', JSON.stringify(userBlocks)); } catch (e) {}
                    closeTopoModal(); blkTab = b.tab; renderBlockMenu(); document.getElementById('menu-blocks').classList.remove('hidden');
                    updateCommandMessageText('MODÈLE 3D : « ' + b.name + ' » ajouté aux blocs (' + (r.i.length / 3).toLocaleString('fr-FR') + ' facettes)' + (ok ? '' : ' — trop gros pour être gardé sur ce poste : il reste dans les plans qui l\'utilisent') + '. Clic pour le poser.'); startStamp(b.id); }, true]]); }
        // enregistrement : les modèles importés utilisés par le plan partent avec lui
        function mdlUsed(list) { const names = new Set(list.filter(s => s.block).map(s => s.block)), out = {}; userBlocks.forEach(b => { if (b.mdl && names.has(b.name) && MDL_STORE[b.mdl]) out[b.mdl] = { m: MDL_STORE[b.mdl], b }; }); return Object.keys(out).length ? out : undefined; }
        function mdlRestore(M) { if (!M || typeof M !== 'object') return; let add = false; Object.keys(M).forEach(id => { const e = M[id]; if (!e || !e.m || !Array.isArray(e.m.parts) || !e.b) return; if (!MDL_STORE[id]) { MDL_STORE[id] = e.m; add = true; } if (!userBlocks.some(b => b.mdl === id)) { userBlocks.push(e.b); add = true; } });
            if (add) { mdlUserSave(); try { localStorage.setItem('momocad-blocks', JSON.stringify(userBlocks)); } catch (e) {} } }
